// Host test: the animated COSMIC MUFFIN clip that is compiled into the firmware (device/cosmic_muffin_clip.h, made by
// tools/gif2radar.py from the owner's gif). The device parses it with the same themepack::parseClip a pack's radar.vid
// goes through, so this holds the generated bytes to that parser: a bad regeneration fails here, not on the board.
// Build: make -C sim test_cosmic_clip
#include "../ui/themepack.h"
#include "../device/cosmic_muffin_clip.h"
#include <cstdio>
#include <cstring>

static int fails = 0;
static void check(const char* what, bool ok) { printf(ok ? "  ok   %s\n" : "  FAIL %s\n", what); if (!ok) fails++; }

int main() {
    themepack::Clip c{}; char why[64] = "";
    const bool ok = themepack::parseClip(COSMIC_CLIP, sizeof COSMIC_CLIP, c, why, sizeof why);
    char m[120]; snprintf(m, sizeof m, "the built-in clip is a valid radar.vid (%s)", why);
    check(m, ok);
    check("102 x 102, the size the radar plays", c.w == 102 && c.h == 102);
    check("a colour clip: it carries its own palette", c.pal != nullptr);
    check("a gentle loop: 1 to 30 fps, more than one frame", c.fps >= 1 && c.fps <= 30 && c.frames > 1);
    check("under the size a pack's clip may have", sizeof COSMIC_CLIP <= (size_t)themepack::MAX_CLIP);
    // frames must not be blank or identical copies of one picture
    const size_t fb = (size_t)(c.w * c.h + 1) / 2;
    bool anyDiff = false, allZero = true;
    for (size_t i = 0; i < fb; i++) { if (c.px[i]) allZero = false; if (c.px[i] != c.px[(size_t)(c.frames / 2) * fb + i]) anyDiff = true; }
    check("the first frame has picture in it", !allZero);
    check("the middle frame differs from the first (it animates)", anyDiff);
    // every palette index addressed is one the palette defines (the format has 16 entries, so any nibble is fine)
    check("the palette is 16 entries of RGB565", themepack::CLIP_PAL_BYTES == 32);
    printf("%s\n", fails ? "FAILED" : "all passed");
    return fails ? 1 : 0;
}
